import { z } from "zod";

/**
 * The screenshots on an app's page of the website ("See it"). Each SCREENSHOT is one screen of the app (a title and a few words) with up to six
 * PICTURES of it: three devices × light and dark. The website shows the device the visitor picks, in the theme the visitor's browser is in (or the one they pick).
 * The platform admin manages them in the console (App Management → the app's tab → Screenshots); the pictures taken from the real apps by
 * mobile-apps/screenshots ship with the website and fill the lists the first time (BUILTIN_APP_SHOTS, generated by that tool).
 */
export const SCREENSHOT_DEVICES = ["tablet-landscape", "tablet-portrait", "phone"];
export const SCREENSHOT_THEMES = ["light", "dark"];

/** What each device is: its name, the size of a picture from the real app (px) — the shape the website's frame is drawn for — and a word for a button. */
export const SCREENSHOT_DEVICE_INFO = {
  "tablet-landscape": { label: "Tablet", sub: "Wide", name: "a tablet held sideways", width: 2560, height: 1600 },
  "tablet-portrait": { label: "Tablet", sub: "Tall", name: "a tablet held upright", width: 1600, height: 2560 },
  phone: { label: "Phone", sub: "", name: "a phone", width: 1440, height: 3120 },
};

export const SCREENSHOT_LIMITS = { shotsPerApp: 12, title: 60, caption: 320, alt: 320, heading: 80, intro: 300 };

const text = (label, max) => z.string().trim().max(max, `${label} can be ${max} characters at most.`);
export const screenshotDeviceSchema = z.enum(SCREENSHOT_DEVICES, { errorMap: () => ({ message: "Choose tablet-landscape, tablet-portrait or phone." }) });
export const screenshotThemeSchema = z.enum(SCREENSHOT_THEMES, { errorMap: () => ({ message: "Choose light or dark." }) });

/** Adding a screenshot: a title is needed; the rest can be written later. */
export const screenshotCreateSchema = z.object({
  title: text("The title", SCREENSHOT_LIMITS.title).min(2, "Give the screenshot a title of at least 2 characters."),
  caption: text("The caption", SCREENSHOT_LIMITS.caption).default(""),
  alt: text("The description", SCREENSHOT_LIMITS.alt).default(""),
});
export const screenshotPatchSchema = z.object({
  title: text("The title", SCREENSHOT_LIMITS.title).min(2, "The title needs at least 2 characters.").optional(),
  caption: text("The caption", SCREENSHOT_LIMITS.caption).optional(),
  alt: text("The description", SCREENSHOT_LIMITS.alt).optional(),
  enabled: z.boolean().optional(),
});

/** The section as a whole (per app): shown or not, its heading and the line under it, and the device shown first. Empty words mean "use the usual ones". */
export const screenshotSectionSchema = z.object({
  enabled: z.boolean().optional(),
  heading: text("The heading", SCREENSHOT_LIMITS.heading).optional(),
  intro: text("The intro", SCREENSHOT_LIMITS.intro).optional(),
  defaultDevice: screenshotDeviceSchema.optional(),
});

/** What the website says when the admin wrote nothing. */
export const defaultScreenshotHeading = (code) => `${code} on every screen`;
export const DEFAULT_SCREENSHOT_INTRO = "Real screens from the app, on a tablet and on a phone, in light and dark. Pick a device and a look.";

/** "tablet-landscape" + "dark" → the name of a picture's slot. */
export const screenshotSlot = (device, theme) => `${device}.${theme}`;

/** How far a picture's shape may be from the device's shape before the console warns (a screenshot from another phone is a little taller or shorter: fine). */
export const SCREENSHOT_SHAPE_TOLERANCE = 0.12;
export function screenshotShapeProblem(device, width, height) {
  const want = SCREENSHOT_DEVICE_INFO[device];
  if (!want || !(width > 0) || !(height > 0)) return "";
  const a = width / height;
  const b = want.width / want.height;
  if (Math.abs(a - b) / b <= SCREENSHOT_SHAPE_TOLERANCE) return "";
  const shape = (w, h) => (w > h ? "wide" : "tall");
  return `This picture is ${shape(width, height)} (${width} × ${height}) but ${want.label.toLowerCase()}${want.sub ? ` · ${want.sub.toLowerCase()}` : ""} pictures are ${shape(want.width, want.height)} (about ${want.width} × ${want.height}). It will look squashed in the frame.`;
}
